import { useFormikContext } from "formik";

import type {
  DatabaseData,
  DatabaseFieldGroup,
  DatabaseFieldOrGroup,
  Engine,
  EngineField,
  EngineKey,
} from "metabase-types/api";

import { isDatabaseFieldGroup, shouldShowField } from "../../utils/schema";
import { DatabaseDetailField } from "../DatabaseDetailField";

import { CustomContainer } from "./container-styles";

interface DatabaseFormBodyDetailsProps {
  fields: DatabaseFieldOrGroup[];
  autofocusFieldName?: string;
  engineKey: EngineKey | undefined;
  engine: Engine | undefined;
  isAdvanced: boolean;
}

export function DatabaseFormBodyDetails({
  fields,
  autofocusFieldName,
  engineKey,
  engine,
  isAdvanced,
}: DatabaseFormBodyDetailsProps) {
  const { values } = useFormikContext<DatabaseData>();

  function renderField(engineField: EngineField) {
    if (!shouldShowField(engineField, isAdvanced, values.details)) {
      return null;
    }

    return (
      <DatabaseDetailField
        key={engineField.name}
        field={engineField}
        autoFocus={autofocusFieldName === engineField.name}
        data-key={engineField.name}
        engineKey={engineKey}
        engine={engine}
      />
    );
  }

  function renderGroup(group: DatabaseFieldGroup) {
    const key = group.fields.map((field) => field.name).join("-");
    return (
      <CustomContainer key={key} containerStyle={group["container-style"]}>
        {group.fields.map(renderField)}
      </CustomContainer>
    );
  }

  return fields.map((field) => {
    if (isDatabaseFieldGroup(field)) {
      return renderGroup(field);
    }

    return renderField(field);
  });
}
import { useFormikContext } from "formik";
import {
  type PropsWithChildren,
  createContext,
  useEffect,
  useState,
} from "react";

import type { DatabaseData } from "metabase-types/api";

import { checkFormIsDirty } from "./utils";

export const FormDirtyStateContext = createContext<boolean>(false);

type ProviderProps = PropsWithChildren<{
  onDirtyStateChange?: (isDirty: boolean) => void;
}>;

/**
 * Custom definition for form dirty state.
 * This is needed because Formik's `dirty` value is not accurate to track actual field updates on our database form (#65988).
 *
 * This should be wrapped in a FormProvider.
 */
export const FormDirtyStateProvider = ({
  children,
  onDirtyStateChange,
}: ProviderProps) => {
  const [isDirty, setIsDirty] = useState<boolean>(false);
  const { initialValues, values } = useFormikContext<DatabaseData>();

  useEffect(() => {
    setIsDirty(checkFormIsDirty(initialValues, values));
  }, [initialValues, values]);

  useEffect(() => {
    onDirtyStateChange?.(isDirty);
  }, [isDirty, onDirtyStateChange]);

  return (
    <FormDirtyStateContext.Provider value={isDirty}>
      {children}
    </FormDirtyStateContext.Provider>
  );
};
import _ from "underscore";

import type { DatabaseData } from "metabase-types/api";

export const checkFormIsDirty = (
  initialValues: DatabaseData,
  currentValues: DatabaseData,
) => {
  const sanitizeValues = (values: DatabaseData) => {
    return {
      ...values,
      // Ignore "advanced-options" when checking if the form is dirty. It is not an actual field.
      details: _.omit(values.details, ["advanced-options"]),
      // These boolean fields are nullable. When null, they are treated as false in the form.
      refingerprint: values.refingerprint || false,
      auto_run_queries: values.auto_run_queries || false,
    };
  };

  return !_.isEqual(
    sanitizeValues(initialValues),
    sanitizeValues(currentValues),
  );
};
import { useContext } from "react";
import { match } from "ts-pattern";
import _ from "underscore";

import type { DatabaseFormValues } from "metabase/databases/types";
import { getDefaultEngineKey } from "metabase/databases/utils/engine";
import {
  getFlattenedFields,
  getValidationSchema,
} from "metabase/databases/utils/schema";
import { useFormErrorMessage } from "metabase/forms";
import type { DatabaseData, Engine, EngineField } from "metabase-types/api";

import { FormDirtyStateContext } from "./context";

export const useHasConnectionError = () => {
  const errorMessage = useFormErrorMessage();
  return !!errorMessage;
};

export const getEngine = (
  engines: Record<string, Engine>,
  engineKey?: string,
) => {
  return engineKey ? engines[engineKey] : undefined;
};

export const getEngineKey = (
  engines: Record<string, Engine>,
  values?: Partial<DatabaseData>,
  isAdvanced?: boolean,
) => {
  if (values?.engine && Object.keys(engines).includes(values.engine)) {
    return values.engine;
  } else if (isAdvanced) {
    return getDefaultEngineKey(engines);
  }
};

export const useIsFormDirty = () => {
  return useContext(FormDirtyStateContext);
};

export const castEngineValues = (
  engines: Record<string, Engine>,
  values: Partial<DatabaseData>,
  isAdvanced: boolean,
): DatabaseData => {
  const engineKey = values.engine;
  const schema = getValidationSchema(
    getEngine(engines, engineKey),
    engineKey,
    isAdvanced,
  );
  return schema.cast(values, { stripUnknown: true });
};

export const getEngineDefaults = (
  engines: Record<string, Engine>,
  engineKey: string | undefined,
  isAdvanced: boolean,
): DatabaseData => castEngineValues(engines, { engine: engineKey }, isAdvanced);

/**
 * Values that describe the engine that was selected rather than the connection itself,
 * so they cannot be carried over to another engine.
 */
const ENGINE_SPECIFIC_KEYS: (keyof DatabaseFormValues)[] = [
  "engine",
  "connection-string",
  "provider_name",
];

export const mergeRetainedValues = (
  previousValues: DatabaseData,
  defaultValues: DatabaseData,
  engine: Engine | undefined,
): DatabaseData => {
  const fields: Record<string, EngineField | undefined> = _.indexBy(
    getFlattenedFields(engine?.["details-fields"] ?? []),
    "name",
  );

  const details = _.mapObject(
    defaultValues.details ?? {},
    (defaultValue, name) => {
      const value = previousValues.details?.[name];
      return canRetainDetail(fields[name], value) ? value : defaultValue;
    },
  );

  return {
    ...defaultValues,
    ..._.omit(previousValues, ENGINE_SPECIFIC_KEYS),
    details,
  };
};

const canRetainDetail = (field: EngineField | undefined, value: unknown) => {
  if (field == null || value == null) {
    return false;
  }

  return match(field.type)
    .with("hidden", () => false)
    .with("integer", () => typeof value === "number")
    .with("boolean", "section", () => typeof value === "boolean")
    .with(
      "string",
      "password",
      "text",
      "select",
      "textFile",
      "info",
      undefined,
      () => typeof value === "string",
    )
    .exhaustive();
};
